 useEffect(()=>{if(!dialog)return;const previous=document.activeElement as HTMLElement|null;const modal=document.querySelector<HTMLElement>('[role=dialog]');const focusable=()=>Array.from(modal?.querySelectorAll<HTMLElement>('button,input,select,textarea,[tabindex="0"]')||[]).filter(e=>!e.hasAttribute('disabled'));focusable()[0]?.focus();const trap=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();setDialog('');}if(e.key==='Tab'){const list=focusable();const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus();};},[dialog]);
